  "landingFaq.documentTitle": "FAQ | {{siteTitle}}",
  "landingFaq.metaDescription": "Frequently asked questions about the barber business platform, from booking and automated reminders to plans, upgrades, and dedicated websites.",
  "landingFaq.badge": "Customer questions",
  "landingFaq.title": "Clear answers to frequently asked questions",
  "landingFaq.intro.1": "Before buying or starting a partnership, it is natural to have detailed questions.",
  "landingFaq.intro.2": "This page answers the most important questions in one place so you can decide faster.",
  "landingFaq.intro.3": "If your answer is not here, contact the consulting team through the contact page.",
  "landingFaq.sectionTitle": "Frequently asked questions",
  "landingFaq.sectionDescription": "Tap any question to see the full answer.",
  "landingFaq.phoneModalTitle": "Contact numbers",
  "landingFaq.phoneModalDescription": "Call for purchase advice and quick setup.",
  "landingFaq.footer": "It is time to modernize your business",
  "landingFaq.defaultFaq.1.question": "What businesses is this system suitable for?",
  "landingFaq.defaultFaq.1.answer": "It is suitable for independent barbers, small salons, multi-person salons, and beauty service businesses.",
  "landingFaq.defaultFaq.2.question": "Can my customers book without training?",
  "landingFaq.defaultFaq.2.answer": "Yes. Sign-in and booking are designed to be simple, and users can book easily with their mobile number.",
  "landingFaq.defaultFaq.3.question": "Can the admin also create bookings manually?",
  "landingFaq.defaultFaq.3.answer": "Yes. Both users and the admin or team can create bookings, and the daily schedule is managed in one panel.",
  "landingFaq.defaultFaq.4.question": "Are appointment reminders automatic or manual?",
  "landingFaq.defaultFaq.4.answer": "Reminders can be sent automatically, and targeted sending is available for promotional campaigns.",
  "landingFaq.defaultFaq.5.question": "Do I get a dedicated website with my own brand?",
  "landingFaq.defaultFaq.5.answer": "Yes. The website is configured with your brand, and using a dedicated domain is also available.",
  "landingFaq.defaultFaq.6.question": "What happens if I want to upgrade my plan later?",
  "landingFaq.defaultFaq.6.answer": "Plans can be upgraded, so you can expand features and user counts as your team grows.",
