  "landingFeatures.documentTitle": "System features | {{siteTitle}}",
  "landingFeatures.metaDescription": "Complete barber platform features including 24/7 online booking, reminder SMS, targeted campaigns, online store, dedicated website, and team management.",
  "landingFeatures.badge": "All system features in one place",
  "landingFeatures.title": "Features built to grow barber businesses",
  "landingFeatures.intro.1": "This page shows all platform capabilities clearly in one place.",
  "landingFeatures.intro.2": "Each section is designed around business outcomes and direct revenue impact.",
  "landingFeatures.intro.3": "From online booking and automatic reminders to customer reactivation and add-on sales, everything works together.",
  "landingFeatures.intro.4": "Dedicated websites and team management are available alongside these features.",
  "landingFeatures.intro.5": "You can return to the main landing page from here to see the operational demo.",
  "landingFeatures.feature.booking.title": "24/7 online booking",
  "landingFeatures.feature.booking.short": "Customers can book at any hour.",
  "landingFeatures.feature.booking.detail": "Bookings can be created by customers and admins, capacity is controlled, and the team's daily schedule stays organized without messaging chaos.",
  "landingFeatures.feature.reminder.title": "Automatic reminders",
  "landingFeatures.feature.reminder.short": "Reduce cancellations and forgotten appointments.",
  "landingFeatures.feature.reminder.detail": "Customers receive reminders before appointments, reducing no-shows and empty salon time.",
  "landingFeatures.feature.campaign.title": "Targeted SMS campaigns",
  "landingFeatures.feature.campaign.short": "Reactivate inactive customers.",
  "landingFeatures.feature.campaign.detail": "Run dedicated campaigns for customers who have not visited for a while or only purchased once, and bring sales back.",
  "landingFeatures.feature.store.title": "Online store",
  "landingFeatures.feature.store.short": "Connect service sales to product sales.",
  "landingFeatures.feature.store.detail": "Sell specialist products alongside services, manage orders, and give customers clear purchase status.",
  "landingFeatures.feature.brand.title": "Dedicated site and domain",
  "landingFeatures.feature.brand.short": "Show your personal brand more professionally.",
  "landingFeatures.feature.brand.detail": "Your site runs under your own brand and creates a professional online presence for new customer acquisition.",
  "landingFeatures.feature.team.title": "Team and access management",
  "landingFeatures.feature.team.short": "For independent barbers and multi-person salons.",
  "landingFeatures.feature.team.detail": "Multi-user plans let you expand your team, manage roles, and control each person's access level.",
  "landingFeatures.feature.checkout.title": "Flexible payment and settlement",
  "landingFeatures.feature.checkout.short": "Payment scenarios matched to your business.",
  "landingFeatures.feature.checkout.detail": "Online payment and other methods are manageable, and transaction status is trackable for admins and customers.",
  "landingFeatures.feature.automation.title": "Message automation",
  "landingFeatures.feature.automation.short": "Automate repetitive work.",
  "landingFeatures.feature.automation.detail": "From occasion-based notifications to scheduled messages, you can automate communication so your team can focus on core services.",
  "landingFeatures.viewDetails": "View details",
