  "landingPreview.faq.1.question": "Who exactly is this system for?",
  "landingPreview.faq.1.answer": "It is suitable for independent professionals, small salons, multi-person teams, nail artists, lash artists, makeup artists, and beauty service businesses.",
  "landingPreview.faq.2.question": "Can my customers use this system?",
  "landingPreview.faq.2.answer": "Yes. Sign-in and booking are simple, and users enter with their mobile number.",
  "landingPreview.faq.3.question": "What if I am closed for a day or the schedule changes?",
  "landingPreview.faq.3.answer": "The admin can manage work schedules, change times, and run notification scenarios.",
  "landingPreview.faq.4.question": "Are SMS messages automatic or manual?",
  "landingPreview.faq.4.answer": "Both are available; reminders can be automatic and promotional campaigns can be targeted.",
  "landingPreview.faq.5.question": "Do I get a dedicated website with my own brand?",
  "landingPreview.faq.5.answer": "Yes, the website is configured with your brand and dedicated domain connection is available.",
  "landingPreview.faq.6.question": "Can I upgrade later or add team members?",
  "landingPreview.faq.6.answer": "You can upgrade any time and expand based on user count and modules.",
  "landingPreview.faq.title": "Real market FAQs",
  "landingPreview.pain.1": "Bookings are still managed through direct messages and WhatsApp",
