  "landingPreview.pain.3": "Empty slots are not filled and revenue is lost",
  "landingPreview.pain.4": "Managing schedules is hard for multi-person teams",
  "landingPreview.pain.5": "Product sales are separate from services and scattered",
  "landingPreview.pain.6": "The salon brand has no dedicated site or official online presence",
  "landingPreview.pain.title": "Common pains in this market",
  "landingPreview.pain.description": "Anything configured in admin is displayed here.",
