  "nutritionWellnessPreview.topbarTitle": "Wellness-Stil",
  "nutritionWellnessPreview.topbarDescription": "Empfehlungsbasierte Vorschau für die Gewichtserhaltung",
  "nutritionWellnessPreview.badge": "Version im Wellness-Stil",
  "nutritionWellnessPreview.title": "Text- und Audioführung für die Gewichtspflege",
  "nutritionWellnessPreview.description": "Statt eines strengen Essensplans zeigt dieses Modell Schritt für Schritt Empfehlungen und geführte Audiodateien.",
  "nutritionWellnessPreview.contentStructure": "Inhalt",
  "nutritionWellnessPreview.recommendationPage": "Seite zur Empfehlung",
  "nutritionWellnessPreview.intent": "Diese Version ist vor allem für die Aufrechterhaltung von Gewicht und einen gesunden Lebensstil konzipiert.",
